        <section x-show="step===2" x-cloak class="space-y-4">
            <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="font-bold text-slate-900">Daftar Produk</h2><p class="mt-1 text-xs text-slate-500">Cari kode, nama, merek, atau tipe. Hasil dicari dari server dan dibatasi 10 produk per halaman.</p></div><label class="relative w-full sm:max-w-lg"><span class="sr-only">Cari produk</span><input x-model="query" @input.debounce.300ms="searchProducts()" type="search" placeholder="Cari produk berdasarkan nama, kode, atau barcode…" class="w-full rounded-lg border-slate-300 pl-3 pr-10 text-sm"><span class="absolute right-3 top-2.5 text-slate-400">⌕</span></label></div><div x-show="loading" class="py-4 text-xs text-slate-500">Mencari produk…</div><div x-show="results.length" class="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-3"><template x-for="product in results" :key="product.id"><button type="button" @click="add(product)" class="flex items-center justify-between gap-3 rounded-lg border border-slate-200 p-3 text-left hover:border-blue-400 hover:bg-blue-50"><span class="min-w-0"><span class="block truncate text-sm font-semibold text-slate-800" x-text="product.name"></span><span class="block text-xs text-slate-500"><span x-text="product.code"></span> · Stok <span x-text="product.stock"></span></span></span><span class="shrink-0 text-xs font-semibold text-blue-700">Tambah</span></button></template></div><div x-show="lastProductPage>1" class="mt-3 flex items-center justify-end gap-2 text-xs"><button type="button" @click="searchProducts(productPage-1)" :disabled="productPage<=1" class="rounded border px-3 py-1.5 disabled:opacity-40">Sebelumnya</button><span x-text="`Halaman ${productPage} dari ${lastProductPage}`" class="text-slate-500"></span><button type="button" @click="searchProducts(productPage+1)" :disabled="productPage>=lastProductPage" class="rounded border px-3 py-1.5 disabled:opacity-40">Berikutnya</button></div><div x-show="query.length>=2 && !loading && !results.length" class="mt-3 rounded-lg bg-slate-50 p-4 text-center text-xs text-slate-500">Produk tidak ditemukan.</div></article>
            <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="mb-4 flex items-center justify-between"><div><h2 class="font-bold text-slate-900">Produk Purchase Order</h2><p class="mt-1 text-xs text-slate-500">Edit jumlah, harga beli, serta diskon per item.</p></div><span class="text-xs font-semibold text-slate-500" x-text="items.length+' item'"></span></div><div class="overflow-x-auto"><table class="min-w-[800px] w-full text-left text-sm"><thead class="bg-slate-50 text-[11px] uppercase text-slate-500"><tr><th class="px-3 py-2">Produk</th><th class="px-3 py-2">Kode</th><th class="px-3 py-2">Stok</th><th class="px-3 py-2">Harga Beli</th><th class="px-3 py-2">Qty</th><th class="px-3 py-2">Diskon</th><th class="px-3 py-2">Subtotal</th><th></th></tr></thead><tbody class="divide-y divide-slate-100"><template x-for="(item,index) in items" :key="item.id"><tr><td class="px-3 py-3 font-medium" x-text="item.name"></td><td class="px-3 py-3 text-slate-500" x-text="item.code"></td><td class="px-3 py-3" x-text="item.stock ?? '—'"></td><td class="px-3 py-3"><input type="number" min="0" step="0.01" x-model.number="item.price" :disabled="step!==2" class="w-32 rounded-md border-slate-300 text-sm"></td><td class="px-3 py-3"><input type="number" min="1" step="1" x-model.number="item.qty" :disabled="step!==2" class="w-20 rounded-md border-slate-300 text-sm"></td><td class="px-3 py-3"><div class="flex gap-1"><select x-model="item.discount_type" :disabled="step!==2" class="w-20 rounded-md border-slate-300 text-xs"><option value="NOMINAL">Rp</option><option value="PERCENT">%</option></select><input type="number" min="0" step="0.01" x-model.number="item.discount_value" :disabled="step!==2" class="w-24 rounded-md border-slate-300 text-sm"></div></td><td class="whitespace-nowrap px-3 py-3 font-semibold" x-text="money(lineSubtotal(item))"></td><td class="px-3 py-3"><button type="button" @click="remove(index)" :disabled="step!==2" class="text-rose-600">Hapus</button></td></tr></template></tbody></table></div><div x-show="items.length===0" class="py-10 text-center text-sm text-slate-500">Cari dan tambahkan produk ke PO ini.</div><template x-for="(item,index) in items" :key="'hidden-'+item.id"><span><input type="hidden" :name="`items[${index}][product_id]`" :value="item.id"><input type="hidden" :name="`items[${index}][qty]`" :value="item.qty"><input type="hidden" :name="`items[${index}][price]`" :value="item.price"><input type="hidden" :name="`items[${index}][discount_type]`" :value="item.discount_type"><input type="hidden" :name="`items[${index}][discount_value]`" :value="item.discount_value"></span></template></article>
        </section>
        <section x-show="step===3" x-cloak class="grid gap-4 xl:grid-cols-[1.4fr_0.8fr]"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-bold text-slate-900">Review Purchase Order</h2><p class="mt-1 text-sm text-slate-500">Periksa kembali supplier, tanggal, item, dan perhitungan sebelum menyimpan.</p><div class="mt-4 grid gap-3 text-sm sm:grid-cols-2"><div><p class="text-xs text-slate-500">Supplier</p><p class="font-semibold" x-text="supplierName()"></p></div><div><p class="text-xs text-slate-500">Tanggal PO</p><p class="font-semibold" x-text="poDate"></p></div><div><p class="text-xs text-slate-500">Estimasi tiba</p><p class="font-semibold" x-text="eta || 'Sesuai jadwal supplier'"></p></div><div><p class="text-xs text-slate-500">Termin</p><p class="font-semibold" x-text="term || 'Belum ditentukan'"></p></div></div><div class="mt-5 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-3 py-2">Produk</th><th class="px-3 py-2">Qty</th><th class="px-3 py-2">Harga</th><th class="px-3 py-2">Diskon</th><th class="px-3 py-2">Subtotal</th></tr></thead><tbody class="divide-y"><template x-for="item in items" :key="item.id"><tr><td class="px-3 py-2" x-text="item.name"></td><td class="px-3 py-2" x-text="item.qty"></td><td class="px-3 py-2" x-text="money(item.price)"></td><td class="px-3 py-2" x-text="money(lineDiscount(item))"></td><td class="px-3 py-2 font-semibold" x-text="money(lineSubtotal(item))"></td></tr></template></tbody></table></div></article><aside class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-bold text-slate-900">Ringkasan Biaya</h2><div class="mt-4 space-y-3"><div class="flex justify-between text-sm"><span class="text-slate-500">Subtotal</span><span x-text="money(subtotal())"></span></div><div class="flex justify-between text-sm"><span class="text-slate-500">Diskon item</span><span x-text="money(discountTotal())"></span></div><label class="block text-sm"><span class="text-slate-600">Ongkir</span><input type="number" name="ongkir" min="0" step="0.01" value="{{ old('ongkir',$purchaseOrder?->ongkir ?? 0) }}" :disabled="step!==3" x-model.number="shipping" class="mt-1 block w-full rounded-lg border-slate-300 text-sm"></label><label class="block text-sm"><span class="text-slate-600">Pajak (%)</span><input type="number" name="pajak_persen" min="0" max="100" step="0.01" value="{{ old('pajak_persen',$purchaseOrder?->pajak_persen ?? 0) }}" :disabled="step!==3" x-model.number="taxRate" class="mt-1 block w-full rounded-lg border-slate-300 text-sm"><span class="mt-1 block text-[11px] text-slate-400">Default tanpa pajak. Isi persentase sesuai faktur supplier.</span></label><div class="flex justify-between text-sm"><span class="text-slate-500">Pajak</span><span x-text="money(tax())"></span></div><div class="flex items-center justify-between rounded-lg bg-blue-50 px-3 py-3 text-blue-900"><span class="font-bold">TOTAL</span><span class="text-xl font-bold" x-text="money(total())"></span></div><div class="rounded-lg border border-amber-100 bg-amber-50 p-3 text-xs leading-5 text-amber-900">PO belum mengubah stok. Status awal: Menunggu Approval.</div></div></aside></section>
        <div class="mt-4 flex flex-wrap justify-between gap-2 rounded-xl border border-slate-200 bg-white p-3"><button type="button" x-show="step>1" @click="step--" class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700">← Kembali</button><a x-show="step===1" href="{{ $purchaseOrder ? route('purchase-orders.show',$purchaseOrder) : route('purchase-orders.index') }}" class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700">Batal</a><span class="flex-1"></span><button type="button" x-show="step<3" @click="next()" class="rounded-lg bg-blue-700 px-5 py-2 text-sm font-semibold text-white">Lanjut ke <span x-text="step===1?'Pilih Produk':'Review & Simpan'"></span> →</button><button type="submit" x-show="step===3" class="rounded-lg bg-blue-700 px-5 py-2 text-sm font-semibold text-white">{{ $editing ? 'Simpan Perubahan' : 'Simpan Purchase Order' }}</button></div>
    </form>
    <script>
        function purchaseOrderForm(initialItems) {
            return {
                step: 1, query: '', results: [], loading: false, productPage: 1, lastProductPage: 1, supplierOptions: @js($suppliers->map(fn($supplier)=>['id'=>$supplier->id,'label'=>$supplier->nama.' · '.($supplier->telepon ?: 'tanpa telepon')])->values()), supplierId: String(@js(old('supplier_id',$purchaseOrder?->supplier_id ?? ''))), supplierText: @js(($selectedSupplier = $suppliers->firstWhere('id',(int)old('supplier_id',$purchaseOrder?->supplier_id))) ? ($selectedSupplier->nama.' · '.($selectedSupplier->telepon ?: 'tanpa telepon')) : ''), poDate: @js(old('tanggal',$purchaseOrder?->tanggal?->format('Y-m-d') ?? now()->toDateString())), eta: @js(old('estimasi_tiba',$purchaseOrder?->estimasi_tiba?->format('Y-m-d') ?? '')), term: @js(old('termin_pembayaran',$purchaseOrder?->termin_pembayaran ?? '')), items: initialItems.map(item => ({stock: null, discount_type: 'NOMINAL', discount_value: item.discount ?? 0, ...item})),
                shipping: Number(@js(old('ongkir',$purchaseOrder?->ongkir ?? 0))), taxRate: Number(@js(old('pajak_persen',$purchaseOrder?->pajak_persen ?? 0))),
                async searchProducts(page=1) {
                    const term = this.query.trim(); if (term.length < 2) { this.results = []; return; }
                    this.loading = true;
                    try { const response = await fetch(`{{ route('purchase-orders.products.search') }}?q=${encodeURIComponent(term)}&page=${page}`, {headers: {'Accept':'application/json'}}); const body = await response.json(); this.results = body.data ?? []; this.productPage=body.current_page ?? 1; this.lastProductPage=body.last_page ?? 1; }
                    catch { this.results = []; } finally { this.loading = false; }
                },
                add(product) { const existing = this.items.find(item => item.id === product.id); if (existing) existing.qty = Number(existing.qty) + 1; else this.items.push({...product, qty: 1, discount_type: 'NOMINAL', discount_value: 0}); },
                remove(index) { this.items.splice(index,1); },
                lineDiscount(item) { const gross = Math.max(0, Number(item.qty||0)*Number(item.price||0)); const value = Number(item.discount_value||0); return Math.min(gross, item.discount_type==='PERCENT' ? gross*Math.min(value,100)/100 : value); },
                lineSubtotal(item) { return Math.max(0, Number(item.qty||0)*Number(item.price||0)-this.lineDiscount(item)); },
                subtotal() { return this.items.reduce((sum,item)=>sum+Number(item.qty||0)*Number(item.price||0),0); },
                discountTotal() { return this.items.reduce((sum,item)=>sum+this.lineDiscount(item),0); },
                tax() { return Math.max(0,(this.subtotal()-this.discountTotal()+Number(this.shipping||0))*Number(this.taxRate||0)/100); },
                total() { return this.subtotal()-this.discountTotal()+Number(this.shipping||0)+this.tax(); },
                money(value) { return 'Rp '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(Number(value||0)); },
                syncSupplier() { const selected=this.supplierOptions.find(option=>option.label===this.supplierText); this.supplierId=selected ? String(selected.id) : ''; },
                supplierName() { return this.supplierOptions.find(option=>String(option.id)===String(this.supplierId))?.label || 'Pilih supplier pada langkah pertama'; },
                next() { if (this.step===1) { this.syncSupplier(); if(!this.supplierId){this.$root.querySelector('[list=purchase-supplier-options]')?.focus();return;} if(!this.poDate){this.$root.querySelector('[name=tanggal]')?.focus();return;} this.step=2; return; } if(this.step===2){ if(!this.items.length){alert('Tambahkan setidaknya satu produk.');return;} if(this.items.some(item=>Number(item.qty)<1 || Number(item.price)<0)){alert('Qty harus minimal 1 dan harga tidak boleh negatif.');return;} this.step=3; } },
            };
        }
    </script>
</x-dashboard-layout>
